4	/**
5	 * Invoice line item shape stored in `Invoice.lineItems` (Json).
6	 * Amounts are integer cents. `amountCents` is authoritative; qty * unitCents
7	 * is used as a fallback when a line omits it.
8	 */
9	export type LineItem = {
10	  description: string;
11	  qty: number;
12	  unitCents: number;
13	  amountCents: number;
14	};
15	
16	export function coerceLineItems(raw: unknown): LineItem[] {
17	  if (!Array.isArray(raw)) return [];
18	  return raw
19	    .filter((x): x is Record<string, unknown> => !!x && typeof x === "object")
20	    .map((x) => {
21	      const qty = Number(x.qty ?? 1) || 0;
22	      const unitCents = Math.round(Number(x.unitCents ?? 0) || 0);
23	      const amountCents = Math.round(
24	        Number(x.amountCents ?? qty * unitCents) || 0
25	      );
26	      return {
27	        description: String(x.description ?? "Item"),
28	        qty,
29	        unitCents,
30	        amountCents,
31	      };
32	    });
33	}
34	
35	/** Compute subtotal / tax / total (all integer cents) for an invoice. */
36	export function invoiceTotals(invoice: Pick<Invoice, "lineItems" | "taxCents" | "amountCents">) {
37	  const items = coerceLineItems(invoice.lineItems);
38	  const subtotalCents = items.reduce((sum, li) => sum + li.amountCents, 0);
39	  const taxCents = invoice.taxCents ?? 0;
40	  // `amountCents` is the stored authoritative total; fall back to computed.
41	  const totalCents = invoice.amountCents ?? subtotalCents + taxCents;
42	  return { items, subtotalCents, taxCents, totalCents };
43	}
44	
45	const STATUS_LABEL: Record<InvoiceStatus, string> = {
46	  OPEN: "Open",
47	  PAID: "Paid",
48	  VOID: "Void",
49	  REFUNDED: "Refunded",
50	};
51	
52	export function invoiceStatusLabel(status: InvoiceStatus): string {
53	  return STATUS_LABEL[status] ?? status;
54	}
