65	/**
66	 * Build the `data` payload for an Invoice row WITHOUT touching the database, so
67	 * a charge site can create the invoice inside its own guarded `$transaction`
68	 * (sharing the charge's idempotency guard) via `tx.invoice.create({ data })`.
69	 * The stored total (`amountCents`) is always derived from line items + tax so
70	 * callers can't desync the stamped total from the itemised breakdown.
71	 */
72	export function invoiceCreateData(opts: InvoiceInput): Prisma.InvoiceUncheckedCreateInput {
73	  const items = opts.lineItems.map((li) => ({
74	    description: String(li.description),
75	    qty: Number(li.qty) || 0,
76	    unitCents: Math.round(Number(li.unitCents) || 0),
77	    amountCents: Math.round(
78	      Number(li.amountCents ?? (Number(li.qty) || 0) * (Number(li.unitCents) || 0)) || 0
79	    ),
80	  }));
81	  const taxCents = Math.round(opts.taxCents ?? 0);
82	  const subtotalCents = items.reduce((s, li) => s + li.amountCents, 0);
83	  const amountCents = subtotalCents + taxCents;
84	  const status = opts.status ?? "OPEN";
85	
86	  return {
87	    userId: opts.userId,
88	    description: opts.description,
89	    lineItems: items,
90	    taxCents,
91	    amountCents,
92	    status,
93	    paidAt: status === "PAID" ? new Date() : null,
94	    periodStart: opts.period?.start ?? null,
95	    periodEnd: opts.period?.end ?? null,
96	  };
97	}
